def h(p):
 d=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(1048576),b''):d.update(b)
 return d.hexdigest()
def obj(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def text(p):return p.read_text(encoding='utf-8-sig')
def safe(p):
 p=p.absolute();assert p.is_relative_to(R)
 for q in [p,*p.parents]:
  if q==R.parent:break
  assert not q.is_symlink() and not (getattr(q.stat(),'st_file_attributes',0)&0x400),str(q)
 return p
def row(p):safe(p);return {'path':str(p),'bytes':p.stat().st_size,'sha256':h(p)}
def inventory(root):return {p.relative_to(root).as_posix():row(p) for p in sorted(root.rglob('*')) if p.is_file()}
def save(n,v):
 p=P/n;p.parent.mkdir(parents=True,exist_ok=True)
