def check_members(names):
 seen=set()
 for n in names:
  p=Path(n);assert not p.is_absolute() and '..' not in p.parts and '\\' not in n
  key=n.casefold();assert key not in seen;seen.add(key)
  assert not any(x in key for x in ['.env','private/','assessment_author','/.git/'])
def check_ready(r):
 if r['status']=='VERIFIED':assert r.get('evidence') and not r.get('pending')
def verify_hash(p,sha):assert h(p)==sha
